//! Tray icons: the GhostPerf ghost while idle, and the same ghost with a red
//! dot while recording. Both come from `assets/icon/` (generated by
//! `assets/build_icons.py`).
//!
//! On Windows they're loaded from the exe's own icon resources, which
//! `build.rs` embeds from the multi-size `.ico` files. They're loaded at the
//! system small-icon size, so the notification area gets the hand-tuned
//! 16/20/24px frames instead of a 32px bitmap scaled down. Elsewhere, or if
//! that load fails, a 32px PNG compiled into the binary is decoded instead.

use std::io::Cursor;

use tray_icon::Icon;

const IDLE_PNG: &[u8] = include_bytes!("../../../assets/icon/png/ghostperf-32.png");
const RECORDING_PNG: &[u8] = include_bytes!("../../../assets/icon/png/ghostperf-recording-32.png");

/// Icon resource IDs assigned in `build.rs`.
#[cfg(windows)]
const IDLE_RESOURCE_ID: u16 = 1;
#[cfg(windows)]
const RECORDING_RESOURCE_ID: u16 = 2;

pub fn idle_icon() -> Icon {
    #[cfg(windows)]
    if let Some(icon) = from_resource(IDLE_RESOURCE_ID) {
        return icon;
    }
    from_png(IDLE_PNG)
}

pub fn recording_icon() -> Icon {
    #[cfg(windows)]
    if let Some(icon) = from_resource(RECORDING_RESOURCE_ID) {
        return icon;
    }
    from_png(RECORDING_PNG)
}

#[cfg(windows)]
fn from_resource(id: u16) -> Option<Icon> {
    use windows::Win32::UI::WindowsAndMessaging::{GetSystemMetrics, SM_CXSMICON, SM_CYSMICON};

    // The notification area uses the small-icon size (16px at 100% scaling,
    // 20px at 125%, 24px at 150%, ...).
    let (w, h) = unsafe { (GetSystemMetrics(SM_CXSMICON), GetSystemMetrics(SM_CYSMICON)) };
    let size = (w > 0 && h > 0).then_some((w as u32, h as u32));
    Icon::from_resource(id, size).ok()
}

fn from_png(bytes: &[u8]) -> Icon {
    // Both inputs are compile-time constants checked by the tests below, so
    // a failure here is a build problem, not a runtime condition.
    let (rgba, width, height) = decode_png(bytes).expect("embedded tray icon PNG is valid");
    Icon::from_rgba(rgba, width, height).expect("decoded tray icon has a consistent size")
}

/// Decodes a PNG to 8-bit RGBA, whatever its stored format.
fn decode_png(bytes: &[u8]) -> Result<(Vec<u8>, u32, u32), png::DecodingError> {
    let mut decoder = png::Decoder::new(Cursor::new(bytes));
    decoder.set_transformations(
        png::Transformations::normalize_to_color8() | png::Transformations::ALPHA,
    );
    let mut reader = decoder.read_info()?;
    let mut buf = vec![
        0;
        reader
            .output_buffer_size()
            .expect("32px icon fits in memory")
    ];
    let info = reader.next_frame(&mut buf)?;
    buf.truncate(info.buffer_size());
    Ok((buf, info.width, info.height))
}

#[cfg(test)]
mod tests {
    use super::*;

    fn pixel(rgba: &[u8], width: u32, x: u32, y: u32) -> [u8; 4] {
        let i = ((y * width + x) * 4) as usize;
        rgba[i..i + 4].try_into().unwrap()
    }

    #[test]
    fn embedded_pngs_decode_to_32px_rgba() {
        for bytes in [IDLE_PNG, RECORDING_PNG] {
            let (rgba, w, h) = decode_png(bytes).unwrap();
            assert_eq!((w, h), (32, 32));
            assert_eq!(rgba.len(), 32 * 32 * 4);
            // Rounded-square background: transparent corner, opaque middle.
            assert_eq!(pixel(&rgba, w, 0, 0)[3], 0, "corner should be transparent");
            assert_eq!(
                pixel(&rgba, w, 16, 10)[3],
                255,
                "ghost body should be opaque"
            );
        }
    }

    #[test]
    fn recording_icon_has_the_red_dot_and_idle_does_not() {
        // Center of the badge (212, 44 in the 256px design), scaled to 32px.
        let (x, y) = (212 * 32 / 256, 44 * 32 / 256);
        let is_red = |p: [u8; 4]| p[0] > 200 && p[1] < 100 && p[2] < 120;

        let (idle, w, _) = decode_png(IDLE_PNG).unwrap();
        let (recording, _, _) = decode_png(RECORDING_PNG).unwrap();
        assert!(
            is_red(pixel(&recording, w, x, y)),
            "recording icon should show the red dot"
        );
        assert!(
            !is_red(pixel(&idle, w, x, y)),
            "idle icon should not show the red dot"
        );
    }

    #[test]
    fn both_icons_construct() {
        // On Windows this goes through the embedded resources (the test binary
        // links them too); elsewhere through the PNG fallback.
        let _ = idle_icon();
        let _ = recording_icon();
    }

    #[cfg(windows)]
    #[test]
    fn icons_load_from_embedded_exe_resources() {
        assert!(
            from_resource(IDLE_RESOURCE_ID).is_some(),
            "idle icon resource missing"
        );
        assert!(
            from_resource(RECORDING_RESOURCE_ID).is_some(),
            "recording icon resource missing"
        );
    }
}
